package com.firetimer;

import lombok.Getter;

@Getter
public enum CampfireLog
{
	// firemakingXpDeltas = the set of integer XP deltas a single log of this
	// type can produce in StatChanged. OSRS tracks XP internally as
	// (actual * 10), so logs with fractional XP (e.g. mahogany 157.5,
	// yew 202.5, magic 303.8, ironwood 220.5) appear as alternating
	// integer deltas as the fractional accumulator rolls over.
	//
	// ticksAdded = burn-time gain when added to a Forester's Campfire.
	// Camphor / Ironwood / Rosewood ticks are linearly extrapolated from
	// the known-level pattern (~0.5 ticks per Firemaking level) -- the
	// OSRS Wiki does not list confirmed values for these three yet.
	LOGS(new int[]{40}, 3),
	OAK_LOGS(new int[]{60}, 10),
	WILLOW_LOGS(new int[]{90}, 17),
	TEAK_LOGS(new int[]{105}, 19),
	ARCTIC_PINE_LOGS(new int[]{125}, 22),
	MAPLE_LOGS(new int[]{135}, 24),
	MAHOGANY_LOGS(new int[]{157, 158}, 26),
	YEW_LOGS(new int[]{202, 203}, 31),
	BLISTERWOOD_LOGS(new int[]{96}, 32),
	CAMPHOR_LOGS(new int[]{180}, 33),                // ticksAdded estimated
	MAGIC_LOGS(new int[]{303, 304}, 38),
	IRONWOOD_LOGS(new int[]{220, 221}, 40),          // ticksAdded estimated
	REDWOOD_LOGS(new int[]{350}, 45),
	ROSEWOOD_LOGS(new int[]{268}, 46);               // ticksAdded estimated

	// A freshly-lit Forester's Campfire burns for
	// (CAMPFIRE_BASE_TICKS + log.ticksAdded) ticks. Refuels add only the
	// log's ticksAdded on top of the current remaining time, capped at
	// FireType.CAMPFIRE.getMaxTicks() (300).
	public static final int CAMPFIRE_BASE_TICKS = 99;

	private final int[] firemakingXpDeltas;
	private final int ticksAdded;

	CampfireLog(int[] firemakingXpDeltas, int ticksAdded)
	{
		this.firemakingXpDeltas = firemakingXpDeltas;
		this.ticksAdded = ticksAdded;
	}

	public static CampfireLog fromFiremakingXpDelta(int xpDelta)
	{
		for (CampfireLog log : values())
		{
			for (int v : log.firemakingXpDeltas)
			{
				if (v == xpDelta)
				{
					return log;
				}
			}
		}
		return null;
	}
}

package com.firetimer;

import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;

@AllArgsConstructor
@Getter
@Setter
public class FireTimeLocation {
    private GameObject fire;
    private final WorldPoint worldPoint;
    private long ticksSinceFireLit;
    private long tickFireStarted;
    private final long tickFireStartedMillis;
    private final FireType fireType;
    private Integer maxTicksOverride;
}

package com.firetimer;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("firetimer")
public interface FireTimerConfig extends Config
{
	enum DisplayUnit
	{
		TICKS("Ticks"),
		MM_SS("Time (m:ss)");

		private final String label;

		DisplayUnit(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
			position = 1,
			keyName = "displayUnit",
			name = "Display unit",
			description = "Show the timer as raw game ticks or as m:ss"
	)
	default DisplayUnit displayUnit()
	{
		return DisplayUnit.TICKS;
	}

	@ConfigItem(
			position = 2,
			keyName = "allowNegative",
			name = "Allow negative",
			description = "When on, refuelable-fire countdowns continue past 0 (e.g. -1, -2) instead of clamping. A signal that someone refueled a campfire after our estimate ran out."
	)
	default boolean allowNegative()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
			position = 3,
			keyName = "normalTimerColor",
			name = "Normal timer color",
			description = "Configures the color of the timer"
	)
	default Color normalTimerColor()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(
			position = 4,
			keyName = "lowTimerColor",
			name = "Low timer color",
			description = "Configures the color of the timer when remaining time is low"
	)
	default Color lowTimerColor()
	{
		return Color.RED;
	}
}

package com.firetimer;

import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import java.awt.*;
import javax.inject.Inject;


public class FireTimerOverlay extends Overlay {
    private final FireTimerPlugin plugin;
    private final FireTimerConfig config;

    @Inject
    FireTimerOverlay(FireTimerPlugin plugin, FireTimerConfig config)
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        this.plugin = plugin;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        this.plugin.getFireIds().forEach((fireIdHash, fireTimeLocation) -> renderTimer(fireTimeLocation, graphics));
        return null;
    }

    private void renderTimer(final FireTimeLocation fireTimeLocation, final Graphics2D graphics)
    {
        FireType fireType = fireTimeLocation.getFireType();
        long elapsedTicks = fireTimeLocation.getTicksSinceFireLit();
        Integer override = fireTimeLocation.getMaxTicksOverride();

        final long ticksValue;
        final Color timerColor;

        if (fireType.isCanRefuel() && override != null)
        {
            long timeLeft = override - elapsedTicks;
            if (!this.config.allowNegative())
            {
                timeLeft = Math.max(0, timeLeft);
            }
            ticksValue = timeLeft;
            timerColor = timeLeft <= fireType.getLowWarningTicks()
                    ? this.config.lowTimerColor()
                    : this.config.normalTimerColor();
        }
        else if (fireType.isCanRefuel())
        {
            ticksValue = Math.max(0, elapsedTicks);
            timerColor = elapsedTicks >= (fireType.getMaxTicks() - fireType.getLowWarningTicks())
                    ? this.config.lowTimerColor()
                    : this.config.normalTimerColor();
        }
        else
        {
            long timeLeft = Math.max(0, fireType.getMaxTicks() - elapsedTicks);
            ticksValue = timeLeft;
            timerColor = timeLeft <= fireType.getLowWarningTicks()
                    ? this.config.lowTimerColor()
                    : this.config.normalTimerColor();
        }

        String displayText;
        if (this.config.displayUnit() == FireTimerConfig.DisplayUnit.TICKS)
        {
            displayText = Long.toString(ticksValue);
        }
        else
        {
            displayText = formatMmSs(fireTimeLocation, fireType, override);
        }

        final Point canvasPoint = fireTimeLocation.getFire().getCanvasTextLocation(graphics, displayText, 40);
        if (canvasPoint != null)
        {
            OverlayUtil.renderTextLocation(graphics, canvasPoint, displayText, timerColor);
        }
    }

    private String formatMmSs(FireTimeLocation loc, FireType fireType, Integer override)
    {
        // Wall-clock-driven so the displayed seconds tick down once per real
        // second instead of jittering with the ~600 ms game tick boundary.
        long elapsedMillis = System.currentTimeMillis() - loc.getTickFireStartedMillis();

        long secondsValue;
        if (fireType.isCanRefuel() && override != null)
        {
            long timeLeftMillis = (long) override * 600L - elapsedMillis;
            if (!this.config.allowNegative())
            {
                timeLeftMillis = Math.max(0L, timeLeftMillis);
            }
            secondsValue = timeLeftMillis / 1000L;
        }
        else if (fireType.isCanRefuel())
        {
            secondsValue = Math.max(0L, elapsedMillis / 1000L);
        }
        else
        {
            long timeLeftMillis = Math.max(0L, (long) fireType.getMaxTicks() * 600L - elapsedMillis);
            secondsValue = timeLeftMillis / 1000L;
        }

        boolean negative = secondsValue < 0;
        long abs = Math.abs(secondsValue);
        long minutes = abs / 60;
        long seconds = abs % 60;
        String formatted = minutes + ":" + (seconds < 10 ? "0" + seconds : Long.toString(seconds));
        return negative ? "-" + formatted : formatted;
    }
}

package com.firetimer;

import com.google.inject.Provides;
import javax.inject.Inject;
import java.util.HashMap;
import java.util.Map;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Fire Timer Plus",
	description = "Adds an in-game timer over player-made fires and Forester's Campfires.",
	tags = {"firemaking", "woodcutting", "forestry", "timer", "campfire", "overlay"}
)
public class FireTimerPlugin extends Plugin
{
	// How long after a firemaking XP drop we'll still attribute a fresh
	// campfire spawn to that drop (handles the case where StatChanged
	// fires before the GameObjectSpawned for the new campfire).
	private static final int RECENT_LOG_TIMEOUT_TICKS = 2;

	// Forester's Campfires get re-instantiated by the engine roughly
	// every 99 ticks (same id, same hash, same tile -- a despawn+respawn
	// pair within one tick) even when nothing visible changes. Defer
	// despawn-driven removal by this many ticks so we can match the
	// respawn and preserve tracking state across the re-instantiation.
	private static final int DESPAWN_GRACE_TICKS = 1;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FireTimerOverlay fireTimerOverlay;

	@Getter(AccessLevel.PACKAGE)
	private long lastTrueTickUpdate;

	@Getter(AccessLevel.PACKAGE)
	private Map<Long, FireTimeLocation> fireIds;

	private int previousFiremakingXp;
	private CampfireLog lastConsumedLog;
	private long lastConsumedLogTick;

	// hash -> tick the despawn was observed; entry lingers in fireIds
	// until either a matching respawn unmarks it, or onGameTick prunes
	// it after the grace window expires.
	private Map<Long, Long> pendingDespawns;

	@Override
	protected void startUp() throws Exception
	{
		this.fireIds = new HashMap<>();
		this.pendingDespawns = new HashMap<>();
		this.previousFiremakingXp = -1;
		this.lastConsumedLog = null;
		this.lastConsumedLogTick = -1;
		this.overlayManager.add(this.fireTimerOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		this.fireIds.clear();
		this.pendingDespawns.clear();
		this.previousFiremakingXp = -1;
		this.lastConsumedLog = null;
		this.lastConsumedLogTick = -1;
		this.overlayManager.remove(this.fireTimerOverlay);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN ||
				event.getGameState() == GameState.HOPPING)
		{
			this.fireIds.clear();
			this.pendingDespawns.clear();
			this.previousFiremakingXp = -1;
			this.lastConsumedLog = null;
			this.lastConsumedLogTick = -1;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FIREMAKING)
		{
			return;
		}

		int currentXp = event.getXp();
		if (this.previousFiremakingXp < 0)
		{
			this.previousFiremakingXp = currentXp;
			return;
		}

		int delta = currentXp - this.previousFiremakingXp;
		this.previousFiremakingXp = currentXp;
		if (delta <= 0)
		{
			return;
		}

		CampfireLog log = CampfireLog.fromFiremakingXpDelta(delta);
		if (log == null)
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		WorldPoint playerLoc = player.getWorldLocation();
		if (playerLoc == null)
		{
			return;
		}

		FireTimeLocation campfire = findAdjacentRefuelableFire(playerLoc);
		if (campfire == null)
		{
			// No campfire adjacent yet -- this might be the lighting log
			// for a campfire that's about to spawn this tick. Hold the
			// log briefly; onGameObjectSpawned will pick it up.
			this.lastConsumedLog = log;
			this.lastConsumedLogTick = this.lastTrueTickUpdate;
			return;
		}

		applyLogToExistingCampfire(campfire, log);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned objectSpawned) {
		GameObject obj = objectSpawned.getGameObject();
		FireType fireType = FireType.fromObjectId(obj.getId());
		if (fireType == null) {
			return;
		}

		// If this respawn matches a pending despawn for the same hash,
		// the engine is just re-instantiating the same campfire. Keep
		// all tracking state and only refresh the GameObject reference.
		if (this.pendingDespawns.remove(obj.getHash()) != null) {
			FireTimeLocation existing = this.fireIds.get(obj.getHash());
			if (existing != null) {
				existing.setFire(obj);
				return;
			}
		}

		Integer maxOverride = null;
		if (fireType.isCanRefuel()
				&& this.lastConsumedLog != null
				&& (this.lastTrueTickUpdate - this.lastConsumedLogTick) <= RECENT_LOG_TIMEOUT_TICKS)
		{
			// XP drop already fired before this spawn -- this is our initial
			// light: 99 base + log.ticksAdded.
			maxOverride = Math.min(
					fireType.getMaxTicks(),
					CampfireLog.CAMPFIRE_BASE_TICKS + this.lastConsumedLog.getTicksAdded()
			);
			this.lastConsumedLog = null;
			this.lastConsumedLogTick = -1;
		}

		this.fireIds.putIfAbsent(obj.getHash(),
				new FireTimeLocation(
						obj,
						obj.getWorldLocation(),
						0,
						this.lastTrueTickUpdate,
						System.currentTimeMillis(),
						fireType,
						maxOverride
				)
		);
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned objectDespawned) {
		GameObject obj = objectDespawned.getGameObject();
		FireType fireType = FireType.fromObjectId(obj.getId());
		if (fireType != null) {
			// Defer removal: the engine often pairs despawn+respawn within
			// the same tick for campfires. onGameTick prunes any pending
			// despawns whose grace window has expired.
			this.pendingDespawns.put(obj.getHash(), this.lastTrueTickUpdate);
		}
	}

	@Subscribe
	public void onGameTick(GameTick change) {
		this.lastTrueTickUpdate = this.client.getTickCount();

		this.fireIds.forEach((fireIdHash, fireTimeLocation) ->
						fireTimeLocation.setTicksSinceFireLit(
								this.lastTrueTickUpdate - fireTimeLocation.getTickFireStarted()));

		// Finalize any pending despawns that didn't get a matching respawn
		// within the grace window.
		this.pendingDespawns.entrySet().removeIf(e -> {
			if (this.lastTrueTickUpdate - e.getValue() > DESPAWN_GRACE_TICKS) {
				this.fireIds.remove(e.getKey());
				return true;
			}
			return false;
		});

		if (this.lastConsumedLog != null
				&& (this.lastTrueTickUpdate - this.lastConsumedLogTick) > RECENT_LOG_TIMEOUT_TICKS)
		{
			this.lastConsumedLog = null;
			this.lastConsumedLogTick = -1;
		}
	}

	@Provides
	FireTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FireTimerConfig.class);
	}

	private FireTimeLocation findAdjacentRefuelableFire(WorldPoint playerLoc)
	{
		for (FireTimeLocation loc : this.fireIds.values())
		{
			if (!loc.getFireType().isCanRefuel())
			{
				continue;
			}
			WorldPoint cf = loc.getFire().getWorldLocation();
			if (cf == null || cf.getPlane() != playerLoc.getPlane())
			{
				continue;
			}
			if (Math.abs(cf.getX() - playerLoc.getX()) <= 1
					&& Math.abs(cf.getY() - playerLoc.getY()) <= 1)
			{
				return loc;
			}
		}
		return null;
	}

	private void applyLogToExistingCampfire(FireTimeLocation campfire, CampfireLog log)
	{
		FireType fireType = campfire.getFireType();
		long elapsed = this.lastTrueTickUpdate - campfire.getTickFireStarted();
		Integer currentMax = campfire.getMaxTicksOverride();

		long newRemaining;
		if (currentMax == null)
		{
			// First log we observe on this campfire. Two sub-cases:
			// (a) Just spawned this tick -- this is the initial light XP
			//     drop arriving after the GameObjectSpawned. Apply 99 base.
			// (b) Walked-up campfire -- conservatively assume 0 prior
			//     remaining and credit only this log's gain.
			if (elapsed <= RECENT_LOG_TIMEOUT_TICKS)
			{
				newRemaining = CampfireLog.CAMPFIRE_BASE_TICKS + log.getTicksAdded();
			}
			else
			{
				newRemaining = log.getTicksAdded();
			}
		}
		else
		{
			long currentRemaining = Math.max(0, currentMax - elapsed);
			newRemaining = currentRemaining + log.getTicksAdded();
		}

		newRemaining = Math.min(fireType.getMaxTicks(), newRemaining);
		campfire.setMaxTicksOverride((int) (elapsed + newRemaining));
	}
}

package com.firetimer;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import lombok.Getter;

@Getter
public enum FireType
{
	// 26185 = the standard player-made cooking fire (deob name FIRE_26185).
	REGULAR_FIRE(setOf(26185), 200, 100, false),

	// Forester's Campfire (Forestry update). The six IDs cover the Regular,
	// Red, Green, Blue, White, and Purple log-color variants. Per the OSRS
	// Wiki the lifetime caps at 300 ticks (~3 min) regardless of refuel;
	// log-type inference and refuel tracking are layered in later phases.
	CAMPFIRE(setOf(49927, 49928, 49929, 49930, 49931, 49932), 300, 100, true);

	private final Set<Integer> objectIds;
	private final int maxTicks;
	private final int lowWarningTicks;
	private final boolean canRefuel;

	FireType(Set<Integer> objectIds, int maxTicks, int lowWarningTicks, boolean canRefuel)
	{
		this.objectIds = objectIds;
		this.maxTicks = maxTicks;
		this.lowWarningTicks = lowWarningTicks;
		this.canRefuel = canRefuel;
	}

	public static FireType fromObjectId(int objectId)
	{
		for (FireType type : values())
		{
			if (type.objectIds.contains(objectId))
			{
				return type;
			}
		}
		return null;
	}

	private static Set<Integer> setOf(int... ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return Collections.unmodifiableSet(set);
	}
}

